class Account {
    private double balance;

    public Account(double opening) {   // CONSTRUCTOR: class name, no return type
        this.balance = opening;        // initialize state
    }

    public void deposit(double amt) {  // METHOD: has a return type (void)
        balance += amt;
    }

    // public void Account() { }       // <-- this is a METHOD, not a constructor!
}

Account a = new Account(100);          // constructor runs once
a.deposit(50);                         // method called as needed
```

