```java
// 1) Singleton
class Config {
    private static final Config INSTANCE = new Config();
    private Config() { }                 // no outside 'new'
    public static Config get() { return INSTANCE; }
}

// 2) Static factory method
class Money {
    private final long cents;
    private Money(long cents) { this.cents = cents; }
    public static Money ofRupees(double r) {       // named, validated creator
        if (r < 0) throw new IllegalArgumentException();
        return new Money(Math.round(r * 100));
    }
}

// 3) Utility class — forbid instantiation
class MathUtils {
    private MathUtils() { }               // cannot be instantiated
    public static int square(int x) { return x * x; }
}
```

